CREATE GENERATOR CNT;
SET GENERATOR CNT TO 10000;

CREATE GENERATOR ID;
SET GENERATOR ID TO 45343;

CREATE GENERATOR RID;
SET GENERATOR RID TO 1000000;


CREATE EXCEPTION INS_PROD_EXCEPT 'Insufficient quantity of product';

SET TERM ^ ;

CREATE PROCEDURE CREATE_100_ORDERS (THREAD_ID INTEGER)
AS
BEGIN
  EXIT;
END^

CREATE PROCEDURE CREATE_MORE_ORDERS
AS
BEGIN
  EXIT;
END^

CREATE PROCEDURE DELETEALL
AS
BEGIN
  EXIT;
END^

CREATE PROCEDURE INITALL (
    CNT NUMERIC(18,0))
AS
BEGIN
  EXIT;
END^

CREATE PROCEDURE FILLX
AS
BEGIN
  EXIT;
END^

SET TERM ; ^


CREATE TABLE CATEGORY (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(20)
);


CREATE TABLE CUSTOMER (
    ID                    NUMERIC(18,0) NOT NULL,
    FIRSTNAME             VARCHAR(50) NOT NULL,
    LASTNAME              VARCHAR(50) NOT NULL,
    ADDRESS1              VARCHAR(50) NOT NULL,
    ADDRESS2              VARCHAR(50),
    CITY                  VARCHAR(50) NOT NULL,
    STATE                 VARCHAR(50),
    ZIP                   INTEGER,
    COUNTRY               VARCHAR(50) NOT NULL,
    REGION                SMALLINT NOT NULL,
    EMAIL                 VARCHAR(50),
    PHONE                 VARCHAR(50),
    CREDITCARDTYPE        SMALLINT NOT NULL,
    CREDITCARD            VARCHAR(50) NOT NULL,
    CREDITCARDEXPIRATION  VARCHAR(50) NOT NULL,
    USERNAME              VARCHAR(50) NOT NULL,
    PASSWD                VARCHAR(50) NOT NULL,
    AGE                   SMALLINT,
    INCOME                NUMERIC(18,0),
    GENDER                VARCHAR(1)
);


CREATE TABLE CUSTOMER_HISTORY (
    CUSTOMER_ID  NUMERIC(18,0) NOT NULL,
    ORDERS_ID    NUMERIC(18,0) NOT NULL,
    PRODUCT_ID   NUMERIC(18,0) NOT NULL
);


CREATE TABLE INVENTORY (
    ID             NUMERIC(18,0) NOT NULL,
    PRODUCT_ID     NUMERIC(18,0) NOT NULL,
    QUAN_IN_STOCK  NUMERIC(18,0) NOT NULL
);


CREATE TABLE CUSTOMERX (
    ID             NUMERIC(18,0) NOT NULL,
    TXT            VARCHAR(32000)
);


CREATE TABLE ORDERLINE (
    ID          NUMERIC(18,0) NOT NULL,
    ORDERS_ID   NUMERIC(18,0) NOT NULL,
    PRODUCT_ID  NUMERIC(18,0) NOT NULL,
    QUANTITY    SMALLINT NOT NULL,
    ORDERDATE   DATE NOT NULL
);


CREATE TABLE ORDERS (
    ID           NUMERIC(18,0) NOT NULL,
    ORDERDATE    DATE NOT NULL,
    CUSTOMER_ID  NUMERIC(18,0),
    NETAMOUNT    NUMERIC(12,2) NOT NULL,
    TAX          NUMERIC(12,2) NOT NULL,
    TOTALAMOUNT  NUMERIC(12,2) NOT NULL,
    TS           TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    THREAD_ID    INTEGER DEFAULT 0
);



CREATE TABLE PRODUCT (
    ID           NUMERIC(18,0) NOT NULL,
    CATEGORY_ID  NUMERIC(18,0) NOT NULL,
    TITLE        VARCHAR(50) NOT NULL,
    ACTOR        VARCHAR(50) NOT NULL,
    PRICE        NUMERIC(12,2) NOT NULL,
    SPECIAL      SMALLINT
);


CREATE TABLE REORDER (
    PRODUCT_ID      NUMERIC(18,0) NOT NULL,
    DATE_LOW        DATE NOT NULL,
    QUAN_LOW        NUMERIC(18,0) NOT NULL,
    DATE_REORDERED  DATE,
    QUAN_REORDERED  NUMERIC(18,0),
    DATE_EXPECTED   DATE
);


CREATE TABLE TMP_ADR (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(50)
);


CREATE TABLE TMP_CITY (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(50)
);


CREATE TABLE TMP_FN (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(20)
);


CREATE TABLE TMP_FN2 (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(20)
);


CREATE TABLE TMP_LN (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(20)
);


CREATE TABLE TMP_LN2 (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(20)
);


CREATE TABLE TMP_STATE (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(2)
);


CREATE TABLE TMP_TITLEWORD (
    ID   NUMERIC(18,0) NOT NULL,
    TXT  VARCHAR(20)
);


commit;

SET AUTODDL OFF;

